const WADIYAR_INFO={id:"krishnaraja-wadiyar-iv",title:"Krishnaraja Wadiyar IV (Mysore's Progressive Maharaja)",reignPeriod:"1902 – 1940 CE",dynasty:"Wadiyar Dynasty of Mysore",capital:"Mysore (Mysuru), Princely State of Mysore",honorific:"Rajarshi (Saintly King - Titled by Mahatma Gandhi)",distinguishedDiwans:"Sir M. Visvesvaraya, Sir K. Seshadri Iyer, Sir Mirza Ismail",quickStats:[{label:"Reign Period",value:"1902 – 1940 CE",icon:"👑"},{label:"State Honorific",value:"Rajarshi (Saintly King)",icon:"✨"},{label:"Famous Diwan",value:"Sir M. Visvesvaraya",icon:"⚙️"},{label:"1st Hydro Station",value:"Shivanasamudra (1902)",icon:"⚡"},{label:"University Foundation",value:"University of Mysore (1916)",icon:"🎓"},{label:"Iconic Palace",value:"Amba Vilas Palace",icon:"🏰"}]},EDUCATION_INSTITUTIONS=[{name:"Indian Institute of Science (IISc), Bangalore",establishedYear:"1909 CE",contribution:"Maharaja donated 371 acres of prime land in Bangalore along with a massive financial grant to establish India's premier science research institute.",category:"Higher Research"},{name:"University of Mysore",establishedYear:"1916 CE",contribution:"First university founded in a princely state in India, championed by Sir M. Visvesvaraya to democratize higher education.",category:"University Education"},{name:"Maharani's Science College & Free Schooling",establishedYear:"1917 CE",contribution:"Introduced free compulsory primary education, establishing specialized science colleges and hostels for women and underprivileged students.",category:"Women & Primary Education"}],INFRASTRUCTURE_PROJECTS=[{title:"Shivanasamudra Hydroelectric Station (1902)",impact:"First major hydroelectric power station in Asia. Electrified the Kolar Gold Fields (KGF) in 1902 and made Bangalore the first city in Asia to have electric streetlights in 1905.",icon:"⚡"},{title:"Krishna Raja Sagara (KRS) Dam & Brindavan Gardens",impact:"Engineering marvel constructed across the Kaveri River by Sir M. Visvesvaraya, providing irrigation to 120,000 acres of arid land and drinking water to Mysore/Bangalore.",icon:"🌊"},{title:"Visvesvaraya Iron and Steel Plant (VISL), Bhadravati",impact:"First public-sector steel plant in South India, driving industrial self-reliance alongside Mysore Soap Factory (Sandalwood Soap) and Mysore Paper Mills.",icon:"🏭"}],CULTURAL_HERITAGE=[{title:"Mysore Amba Vilas Palace",description:"Commissioned the reconstruction of the majestic Indo-Saracenic royal palace after the wooden palace burnt down in 1897; designed by Henry Irwin and completed in 1912."},{title:"Mysore Dasara Festival & Carnatic Music",description:"Elevated the 10-day Vijayadashami Dasara procession to world renown; patronized Carnatic legends including Veena Seshanna, Mysuru Chowdiah, and royal court painters."}],TIMELINE_EVENTS=[{year:"1884 CE",title:"Birth of Krishnaraja Wadiyar IV",description:"Born at Mysore Palace to Maharaja Chamarajendra Wadiyar X and Maharani Kempananjammani."},{year:"1902 CE",title:"Attainment of Majority & Accession",description:"Assumes full ruling powers of Mysore; inaugurates Shivanasamudra Hydroelectric Plant."},{year:"1909 CE",title:"Establishment of IISc Bangalore",description:"Grafts 371 acres of land and capital funds for Jamsetji Tata's vision of IISc."},{year:"1911–1918 CE",title:"Visvesvaraya Era & KRS Dam Construction",description:"Appoints Sir M. Visvesvaraya as Chief Engineer and Diwan; constructs KRS Dam and Mysore University."},{year:"1940 CE",title:"Legacy & Passing",description:"Concludes 38-year progressive reign, leaving Mysore as the most industrialized and literate princely state in British India."}],REFERENCES=[{text:"Rao, C. Hayavadana (1936). Mysore Gazetteer. Government Press, Bangalore.",link:"#"},{text:"Visvesvaraya, M. (1951). Memoirs of My Working Life. National Book Trust, India.",link:"#"},{text:"Bhagavan, Manu (2003). Sovereign Spheres: Princes, Education and Empire in Colonial India. Oxford University Press.",link:"#"}];"undefined"!=typeof m